push.css:
.fxs .tn{--pushA:#22307A;--pushB:#0E1640;--pushC:#F4D27A;--rim:#F4D27A;--rimD:#0E1640}
.fxs .push.tn{--pr:22px;background:none;border-radius:22px;box-shadow:0 7px 0 #0A0F30,0 18px 26px rgba(0,0,0,.45)}
.fxs .push.tn span{font:400 42px/1 "Yuji Mai",serif;letter-spacing:.08em;color:#FFE9A8;text-shadow:0 2px 0 #3A2A10,0 0 12px rgba(244,210,122,.55)}
.fxs .push.tn::after{border-radius:36px;border-color:rgba(244,210,122,.85)}
.fxs .tn .tnf{position:absolute;left:0;top:0;width:200px;height:100px;border-radius:22px;overflow:hidden;pointer-events:none;font-style:normal}
.fxs .tn .tnf svg{display:block;width:200px;height:100px}
.fxs .tn .tnd{position:absolute;left:-40px;top:-60px;width:280px;height:200px;pointer-events:none;z-index:3;font-style:normal}
.fxs .tn .tnd svg{display:block;width:280px;height:200px;overflow:visible}
.fxs .tn .tnfz{transform-box:view-box;animation:fxtnfSw 2.8s ease-in-out infinite}
@keyframes fxtnfSw{0%,100%{transform:rotate(-9deg)}50%{transform:rotate(8deg)}}
.fxs .tn .tnft{transform-box:fill-box;transform-origin:50% 50%;animation:fxtnfTw 2.8s ease-in-out infinite}
@keyframes fxtnfTw{0%,100%{opacity:.35;transform:scale(.7)}50%{opacity:1;transform:scale(1.05)}}
.fxs .pshadow.tn{width:220px}
.fxs .tap.tn{font-family:"Yuji Mai",serif;font-weight:400;color:#FFE9A8;letter-spacing:.14em;text-shadow:0 2px 0 #0E1640,0 0 10px rgba(244,210,122,.6)}
.fxs .pressed.tn{border-radius:22px;background:#1A2566;box-shadow:0 0 0 3px #F4D27A,0 7px 0 3px #0A0F30;animation-name:fxtnPress,fxfxH}
@keyframes fxtnPress{0%{transform:scale(1)}22%{transform:scale(.92)}45%{transform:scale(1.06)}100%{transform:scale(1.45);opacity:0}}
@media (prefers-reduced-motion:reduce){.fxs .tn .tnfz,.fxs .tn .tnft{animation:none}
.fxs .clips.tn{display:none}}
.fxs .clips.tn{position:absolute;z-index:4;left:50%;top:calc(50% - 40px);width:0;height:0}
.fxs .clips.tn i{position:absolute;opacity:0;left:calc(var(--z) / -2);top:calc(var(--z) / -2);width:var(--z);height:var(--z);animation:fxtnFly 1.5s cubic-bezier(.2,.6,.4,1) calc(var(--d) + .1s) both;background:center/contain no-repeat}
